"use client"

import { createParts } from "@ui-sdk/react/primitive"
import { Slider, SliderControl, SliderThumb, SliderTrack, type SliderValueChangeDetails } from "@ui-sdk/react/slider"
import { Toggle, ToggleIcon } from "@ui-sdk/react/toggle"
import { LockIcon, LockOpenIcon } from "lucide-react"
import { memo, useCallback, useMemo, useRef, useState } from "react"

import { evenly, rebalance, type MixerValues } from "@/components/ui/mixer-balance"
import { mixer } from "@/components/ui/mixer-primitive"
import { ControlTooltip } from "@/components/ui/tooltip"
import { useLocale } from "@/lib/locale"
import { cn, cssVars } from "@/lib/utils"

const { Root: MixerRoot } = createParts(mixer, { root: "div" })

/** A channel strip: `id` keys its value, `label` names its fader and is printed on its strip. */
type MixerChannel = { id: string; label: string }

type MixerLabels = {
  /** Names a channel's lock button; it gets the channel's label. */
  lock: (channel: string) => string
  /** The readout's term for the sum of every channel. */
  total: string
}

const mixerLabels: MixerLabels = {
  lock: (channel) => `Lock ${channel}`,
  total: "Total",
}

/** Why the values or the locks changed, and `cancel()` to keep them as they were. */
type MixerChangeDetails = {
  reason: string
  /** The channel moved by hand or by `setChannel`; undefined for `setAll`. */
  channel: string | undefined
  event: Event | undefined
  cancel: () => void
  readonly canceled: boolean
}

type MixerState = { disabled: boolean; values: MixerValues; locked: readonly string[] }

type MixerProps = {
  /** The accessible name of the mixer as a whole. */
  label: string
  channels: readonly MixerChannel[]
  /** Each channel's share by id. Pass it to control the mixer; the values should sum to `total`. */
  value?: MixerValues
  /** The total split evenly by default. */
  defaultValue?: MixerValues
  /** Runs on every step of a drag, a key or an agent's call, with every channel's new value. */
  onValueChange?: (values: MixerValues, details: MixerChangeDetails) => void
  /** Runs once a drag, a key press or an agent's call that changed the values ends, for saving. */
  onValueCommit?: (values: MixerValues) => void
  /** The ids of the channels rebalancing leaves put. Pass it to control the locks. */
  locked?: readonly string[]
  defaultLocked?: readonly string[]
  onLockedChange?: (locked: string[], details: MixerChangeDetails) => void
  /** What the channels always sum to; 100 by default. */
  total?: number
  /** The smallest change of a channel; 1 by default. Page Up and Page Down move ten steps. */
  step?: number
  /** How values read on the strips and for screen readers: `Intl.NumberFormat` options, or a function. */
  format?: Intl.NumberFormatOptions | ((value: number) => string)
  /** The locale values are written in; the page's `lang`, or the runtime's default without one. */
  locale?: string
  disabled?: boolean
  labels?: Partial<MixerLabels>
  /** Classes for the root; a function gets the mixer's state. */
  className?: string | ((state: MixerState) => string | undefined)
}

function details(reason: string, channel: string | undefined, event: Event | undefined): MixerChangeDetails {
  let canceled = false
  return {
    reason,
    channel,
    event,
    cancel: () => {
      canceled = true
    },
    get canceled() {
      return canceled
    },
  }
}

const noLocks: readonly string[] = []
const ledCount = 14
const leds = Array.from({ length: ledCount }, (_, index) => index)
const ledTone = (index: number) => (index >= ledCount - 2 ? "peak" : index >= ledCount - 5 ? "hot" : "signal")
const scaleMarks = [0, 0.25, 0.5, 0.75, 1]

type LockCommit = (id: string, lock: boolean, event: Event | undefined, reason?: string) => boolean

const ChannelHead = memo(function ChannelHead({
  id,
  number,
  name,
  pressed,
  disabled,
  onLock,
}: {
  id: string
  number: number
  name: string
  pressed: boolean
  disabled: boolean
  onLock: LockCommit
}) {
  return (
    <div data-slot="mixer-channel-head">
      <span data-slot="mixer-channel-number" aria-hidden="true">
        {number}
      </span>
      <ControlTooltip label={name}>
        <Toggle
          aria-label={name}
          pressed={pressed}
          disabled={disabled}
          onPressedChange={(next, change) => {
            if (!onLock(id, next, change.event, change.reason)) change.cancel()
          }}
          className="touch-target"
        >
          <ToggleIcon>{pressed ? <LockIcon /> : <LockOpenIcon />}</ToggleIcon>
        </Toggle>
      </ControlTooltip>
    </div>
  )
})

const Scale = memo(function Scale({ total, format }: { total: number; format: (value: number) => string }) {
  return (
    <div data-slot="mixer-scale" aria-hidden="true">
      {scaleMarks.map((mark) => (
        <span key={mark} style={cssVars({ "--mixer-mark": String(mark) })}>
          {format(mark * total)}
        </span>
      ))}
    </div>
  )
})

function useFormat(format: MixerProps["format"], locale: string | undefined) {
  return useMemo(() => {
    if (typeof format === "function") return format
    const number = new Intl.NumberFormat(locale, format ?? { maximumFractionDigits: 2 })
    return (value: number) => number.format(value)
  }, [format, locale])
}

/**
 * A mixing desk for splitting a total between channels: moving one fader moves the unlocked others in proportion, so
 * the channels always sum to `total`, and a locked channel stays put. Each fader is UI SDK's vertical slider, named by
 * its channel, with a level meter beside it; each lock is a toggle.
 */
function Mixer({
  label,
  channels,
  value,
  defaultValue,
  onValueChange,
  onValueCommit,
  locked: lockedProp,
  defaultLocked = noLocks,
  onLockedChange,
  total = 100,
  step = 1,
  format,
  locale: localeProp,
  disabled = false,
  labels: labelOverrides,
  className,
}: MixerProps) {
  const labels = { ...mixerLabels, ...labelOverrides }
  const ids = channels.map((channel) => channel.id)
  const [ownValues, setOwnValues] = useState(() => defaultValue ?? evenly(ids, total, step))
  const [ownLocked, setOwnLocked] = useState<readonly string[]>(defaultLocked)
  const values = value ?? ownValues
  const locked = lockedProp ?? ownLocked
  const latest = useRef(values)
  const anchor = useRef<MixerValues | null>(null)
  const locale = useLocale(localeProp)
  const formatValue = useFormat(format, locale)
  const balance = { ids, values, locked: new Set(locked), total, step }

  const apply = (next: MixerValues, change: MixerChangeDetails) => {
    onValueChange?.(next, change)
    if (change.canceled) return false
    latest.current = next
    setOwnValues(next)
    return true
  }

  const commit = (next: MixerValues, { channel, event }: { channel: string | undefined; event: Event | undefined }) => {
    const done = apply(next, details("imperative", channel, event))
    if (done) onValueCommit?.(next)
    return done
  }

  const commitLock = useCallback<LockCommit>(
    (id, lock, event, reason = "imperative") => {
      const next = lock ? [...locked.filter((other) => other !== id), id] : locked.filter((other) => other !== id)
      const change = details(reason, id, event)
      onLockedChange?.(next, change)
      if (change.canceled) return false
      setOwnLocked(next)
      return true
    },
    [locked, onLockedChange],
  )

  const onFader = (id: string) => (next: number, change: SliderValueChangeDetails) => {
    if (anchor.current === null) anchor.current = values
    const moved = apply(rebalance(balance, id, next, anchor.current), details(change.reason, id, change.event))
    if (!moved) change.cancel()
  }

  const onFaderCommit = () => {
    anchor.current = null
    onValueCommit?.(latest.current)
  }

  const state = { disabled, values, locked }
  const sum = ids.reduce((all, id) => all + (values[id] ?? 0), 0)

  return (
    <MixerRoot
      channels={channels}
      values={values}
      locked={locked}
      total={total}
      step={step}
      disabled={disabled}
      commit={commit}
      commitLock={commitLock}
      aria-label={label}
      className={cn(
        "flex w-full flex-col overflow-hidden rounded-surface border bg-card text-card-foreground shadow-surface",
        typeof className === "function" ? className(state) : className,
      )}
    >
      <div data-slot="mixer-desk" data-disabled={disabled ? "" : undefined}>
        <div data-slot="mixer-strips">
          {channels.map((channel, index) => {
            const level = values[channel.id] ?? 0
            const isLocked = locked.includes(channel.id)
            const lit = Math.round((level / total) * ledCount)
            return (
              <div
                key={channel.id}
                data-slot="mixer-channel"
                data-locked={isLocked ? "" : undefined}
                style={cssVars({ "--mixer-level": (level / total).toFixed(4) })}
              >
                <ChannelHead
                  id={channel.id}
                  number={index + 1}
                  name={labels.lock(channel.label)}
                  pressed={isLocked}
                  disabled={disabled}
                  onLock={commitLock}
                />
                <div data-slot="mixer-fader">
                  <Scale total={total} format={formatValue} />
                  <Slider
                    value={level}
                    onValueChange={onFader(channel.id)}
                    onValueCommit={onFaderCommit}
                    orientation="vertical"
                    min={0}
                    max={total}
                    step={step}
                    largeStep={step * 10}
                    disabled={disabled}
                    readOnly={isLocked}
                    format={formatValue}
                    locale={locale}
                    className="h-full"
                  >
                    <SliderControl className="h-full">
                      <SliderTrack>
                        <SliderThumb aria-label={channel.label} className="touch-target" />
                      </SliderTrack>
                    </SliderControl>
                  </Slider>
                  <div data-slot="mixer-meter" aria-hidden="true">
                    {leds.map((led) => (
                      <span key={led} data-tone={ledTone(led)} data-lit={led < lit ? "" : undefined} />
                    ))}
                  </div>
                </div>
                <output data-slot="mixer-value" aria-hidden="true">
                  {formatValue(level)}
                </output>
                <span data-slot="mixer-label" title={channel.label}>
                  {channel.label}
                </span>
              </div>
            )
          })}
        </div>
      </div>
      <dl className="flex items-baseline justify-between gap-group px-inset-surface py-inset-item">
        <dt className="text-meta tracking-meta text-muted-foreground uppercase">{labels.total}</dt>
        <dd className="font-mono text-title-sm tabular-nums">{formatValue(Math.round(sum * 1e6) / 1e6)}</dd>
      </dl>
    </MixerRoot>
  )
}

export { Mixer, mixerLabels }
export type { MixerChangeDetails, MixerChannel, MixerLabels, MixerProps, MixerState, MixerValues }

import { definePrimitive } from "@ui-sdk/core"

import { blocked, rebalance, sumOf, unitsOf, type Balance, type MixerValues } from "@/components/ui/mixer-balance"
import { settled, unavailable } from "@/lib/action-refusal"

type MixerChannelInfo = { id: string; label: string }

/** What a change asks of the app: it returns `false` when the app cancelled it. */
type MixerCommit = (values: MixerValues, change: { channel: string | undefined; event: Event | undefined }) => boolean
type MixerLockCommit = (id: string, locked: boolean, event: Event | undefined) => boolean

type MixerOptions = {
  channels?: readonly MixerChannelInfo[]
  values?: MixerValues
  locked?: readonly string[]
  total?: number
  step?: number
  disabled?: boolean
  commit?: MixerCommit
  commitLock?: MixerLockCommit
}

type Ready = {
  balance: Balance
  channels: readonly MixerChannelInfo[]
  commit: MixerCommit
  commitLock: MixerLockCommit
}

function ready(options: MixerOptions, action: string, event: Event | undefined): Ready | false {
  if (options.disabled) return unavailable(action, "isn't available while the mixer is disabled", { event })
  const { channels, values, commit, commitLock } = options
  if (!channels || !values || !commit || !commitLock)
    return unavailable(action, "isn't available: the mixer isn't ready", { event })
  const balance = {
    ids: channels.map((channel) => channel.id),
    values,
    locked: new Set(options.locked),
    total: options.total ?? 100,
    step: options.step ?? 1,
  }
  return { balance, channels, commit, commitLock }
}

const nameOf = (channels: readonly MixerChannelInfo[], id: string) =>
  channels.find((channel) => channel.id === id)?.label ?? id

const known = (channels: readonly MixerChannelInfo[]) =>
  channels.map((channel) => JSON.stringify(channel.id)).join(", ")

function valuesFrom(input: unknown, channels: readonly MixerChannelInfo[]): MixerValues | undefined {
  if (Array.isArray(input)) {
    if (input.length !== channels.length || !input.every((value) => typeof value === "number")) return undefined
    return Object.fromEntries(channels.map((channel, index) => [channel.id, Number(input[index])]))
  }
  if (typeof input !== "object" || input === null) return undefined
  const entries = Object.entries(input)
  if (!entries.every(([, value]) => typeof value === "number")) return undefined
  return Object.fromEntries(entries.map(([id, value]) => [id, Number(value)]))
}

/** A mixer's agent surface: channel shares that always sum to the total, where locked channels stay put. */
const mixer = definePrimitive({
  name: "mixer",
  options: {
    channels: "value",
    values: "value",
    locked: "value",
    total: "value",
    step: "value",
    disabled: "value",
    commit: "value",
    commitLock: "value",
  },
  // Workaround: not `disabled`: the bridge would hide every action from a disabled part without saying why.
  state: (options: MixerOptions) => ({ inert: Boolean(options.disabled) }),
  sync: (options) => ({ inert: Boolean(options.disabled) }),
  api: (context) => ({
    /** Sets one channel by id and rebalances the unlocked others in proportion, so the total holds. */
    setChannel(id: string, value: number, event?: Event) {
      const mixerReady = ready(context.options(), "setChannel", event)
      if (mixerReady === false) return false
      const { balance, channels, commit } = mixerReady
      const name = nameOf(channels, id)
      const why = blocked(balance, id, value)
      if (why?.kind === "unknown")
        return unavailable("setChannel", `has no channel ${JSON.stringify(id)}; the channels are ${known(channels)}`, {
          event,
        })
      if (why?.kind === "range")
        return unavailable("setChannel", `takes 0 to ${String(balance.total)}, not ${String(value)}`, { event })
      if (why?.kind === "locked") return unavailable("setChannel", `can't move ${name}: it is locked`, { event })
      if (why?.kind === "alone") {
        return unavailable(
          "setChannel",
          `can't move ${name}: every other channel is locked, so nothing can make up the difference`,
          { event },
        )
      }
      if (why?.kind === "over") {
        return unavailable(
          "setChannel",
          `can't set ${name} to ${String(value)}: locked channels hold ${String(why.held)} of ${String(balance.total)}, so it can take at most ${String(why.most)}`,
          { event },
        )
      }
      if (unitsOf(value, balance.step) === unitsOf(balance.values[id] ?? 0, balance.step)) return true
      return settled(commit(rebalance(balance, id, value), { channel: id, event }), "setChannel", { event })
    },
    /** Sets every channel at once, by id or in order; they must sum to the total and keep locked channels as they are. */
    setAll(values: MixerValues | number[], event?: Event) {
      const mixerReady = ready(context.options(), "setAll", event)
      if (mixerReady === false) return false
      const { balance, channels, commit } = mixerReady
      const next = valuesFrom(values, channels)
      if (!next) {
        return unavailable(
          "setAll",
          `takes one number per channel, in order or by id (${known(channels)}), not ${JSON.stringify(values)}`,
          { event },
        )
      }
      const missing = balance.ids.filter((id) => !(id in next))
      if (missing.length > 0)
        return unavailable("setAll", `is missing ${missing.map((id) => nameOf(channels, id)).join(", ")}`, { event })
      const stranger = Object.keys(next).find((id) => !balance.ids.includes(id))
      if (stranger !== undefined)
        return unavailable(
          "setAll",
          `has no channel ${JSON.stringify(stranger)}; the channels are ${known(channels)}`,
          { event },
        )
      const outside = balance.ids.find((id) => (next[id] ?? 0) < 0 || (next[id] ?? 0) > balance.total)
      if (outside !== undefined)
        return unavailable(
          "setAll",
          `takes 0 to ${String(balance.total)} per channel, not ${String(next[outside])} for ${nameOf(channels, outside)}`,
          { event },
        )
      const sum = sumOf(balance.ids, next)
      if (unitsOf(sum, balance.step) !== unitsOf(balance.total, balance.step))
        return unavailable("setAll", `needs values that sum to ${String(balance.total)}, not ${String(sum)}`, { event })
      const moved = balance.ids.find(
        (id) =>
          balance.locked.has(id) &&
          unitsOf(next[id] ?? 0, balance.step) !== unitsOf(balance.values[id] ?? 0, balance.step),
      )
      if (moved !== undefined) {
        return unavailable(
          "setAll",
          `can't move ${nameOf(channels, moved)}: it is locked at ${String(balance.values[moved])}`,
          { event },
        )
      }
      const snapped = Object.fromEntries(
        balance.ids.map((id) => [id, unitsOf(next[id] ?? 0, balance.step) * balance.step]),
      )
      if (balance.ids.every((id) => snapped[id] === balance.values[id])) return true
      return settled(commit(snapped, { channel: undefined, event }), "setAll", { event })
    },
    /** Locks a channel so rebalancing leaves it put, or unlocks it with `false`. */
    lock(id: string, locked = true, event?: Event) {
      const mixerReady = ready(context.options(), "lock", event)
      if (mixerReady === false) return false
      const { balance, channels, commitLock } = mixerReady
      if (!balance.ids.includes(id))
        return unavailable("lock", `has no channel ${JSON.stringify(id)}; the channels are ${known(channels)}`, {
          event,
        })
      if (balance.locked.has(id) === locked) return true
      return settled(commitLock(id, locked, event), "lock", { event })
    },
  }),
  slots: (slot) => ({
    root: slot({
      role: "group",
      attrs: (state) => ({ "data-disabled": state.inert ? "" : undefined }),
    }),
  }),
  agent: { actions: ["setChannel", "setAll", "lock"] },
})

export { mixer }
export type { MixerChannelInfo, MixerCommit, MixerLockCommit, MixerOptions }

/** Each channel's share, by channel id. */
type MixerValues = Record<string, number>

type Balance = {
  ids: readonly string[]
  values: MixerValues
  locked: ReadonlySet<string>
  total: number
  step: number
}

/** Why a channel can't take a value, or `undefined` when it can. */
type Blocked =
  | { kind: "unknown" }
  | { kind: "locked" }
  | { kind: "range" }
  | { kind: "alone"; held: number }
  | { kind: "over"; held: number; most: number }

const unitsOf = (value: number, step: number) => Math.round(value / step)

const lockedOthers = ({ ids, values, locked }: Balance, id: string) =>
  ids.filter((other) => other !== id && locked.has(other)).reduce((sum, other) => sum + (values[other] ?? 0), 0)

/** The most a channel can take: the total less what the other locked channels hold. */
const ceilingOf = (balance: Balance, id: string) => balance.total - lockedOthers(balance, id)

function blocked(balance: Balance, id: string, value: number): Blocked | undefined {
  if (!balance.ids.includes(id)) return { kind: "unknown" }
  if (!Number.isFinite(value) || value < 0 || value > balance.total) return { kind: "range" }
  const current = balance.values[id] ?? 0
  if (unitsOf(value, balance.step) === unitsOf(current, balance.step)) return undefined
  if (balance.locked.has(id)) return { kind: "locked" }
  const held = lockedOthers(balance, id)
  const free = balance.ids.filter((other) => other !== id && !balance.locked.has(other))
  if (free.length === 0) return { kind: "alone", held }
  if (value > balance.total - held) return { kind: "over", held, most: balance.total - held }
  return undefined
}

function shareUnits(weights: readonly number[], units: number) {
  const sum = weights.reduce((total, weight) => total + weight, 0)
  const exact = weights.map((weight) => (sum > 0 ? (weight / sum) * units : units / weights.length))
  const shares = exact.map(Math.floor)
  let left = units - shares.reduce((total, share) => total + share, 0)
  const byRemainder = exact.map((value, index) => ({ index, remainder: value - Math.floor(value) }))
  byRemainder.sort((a, b) => b.remainder - a.remainder || a.index - b.index)
  for (const { index } of byRemainder) {
    if (left <= 0) break
    shares[index] = (shares[index] ?? 0) + 1
    left--
  }
  return shares
}

/**
 * Sets one channel and moves every unlocked other in proportion to its share, so the values still sum to the total.
 * The value is snapped to the step and clamped to what the locked channels leave; with no free channel to give or
 * take, nothing moves. `weights` are the shares to keep in proportion, the values when a drag began by default, so a
 * channel pushed to the top and back gives every other its share back.
 */
function rebalance(balance: Balance, id: string, value: number, weights: MixerValues = balance.values): MixerValues {
  const { ids, values, locked, step } = balance
  const free = ids.filter((other) => other !== id && !locked.has(other))
  if (locked.has(id) || free.length === 0) return values
  const ceilingUnits = unitsOf(ceilingOf(balance, id), step)
  const ownUnits = Math.max(0, Math.min(ceilingUnits, unitsOf(value, step)))
  const shares = shareUnits(
    free.map((other) => weights[other] ?? 0),
    ceilingUnits - ownUnits,
  )
  const next: MixerValues = { ...values, [id]: ownUnits * step }
  free.forEach((other, index) => {
    next[other] = (shares[index] ?? 0) * step
  })
  for (const other of ids) next[other] = Math.round((next[other] ?? 0) * 1e6) / 1e6
  return next
}

/** Splits the total evenly, in steps, the first channels taking any remainder. */
function evenly(ids: readonly string[], total: number, step: number): MixerValues {
  const shares = shareUnits(
    ids.map(() => 1),
    unitsOf(total, step),
  )
  return Object.fromEntries(ids.map((id, index) => [id, (shares[index] ?? 0) * step]))
}

const sumOf = (ids: readonly string[], values: MixerValues) => ids.reduce((sum, id) => sum + (values[id] ?? 0), 0)

export { blocked, ceilingOf, evenly, rebalance, sumOf, unitsOf }
export type { Balance, Blocked, MixerValues }
